-- Tropes and content warnings: readers can tag a book in their review, and each book
-- shows community counts ("Enemies to Lovers · 3").
--
-- * tags: the fixed lists (from supabase/data/*.csv, generated by generate_tags_sql.py).
-- * review_tags: which tags a review picked.
-- * save_review(): saves a review and its tags together.
-- * book_tag_counts(): how many readers picked each tag for a book. Reviews stay private;
--   only these totals are shared.

create type public.tag_kind as enum ('trope', 'content_warning');

create table public.tags (
  id integer generated always as identity primary key,
  kind public.tag_kind not null,
  slug text not null,
  name text not null,
  category text not null,
  position integer not null, -- order within its list, as in the CSV
  constraint tags_kind_slug_unique unique (kind, slug)
);

alter table public.tags enable row level security;

create policy "Signed-in users can view tags"
  on public.tags for select
  to authenticated
  using (true);

create table public.review_tags (
  review_id uuid not null references public.reviews (id) on delete cascade,
  tag_id integer not null references public.tags (id) on delete cascade,
  primary key (review_id, tag_id)
);

create index review_tags_tag_id_idx on public.review_tags (tag_id);

alter table public.review_tags enable row level security;

create policy "Users can view tags on their own reviews"
  on public.review_tags for select
  to authenticated
  using (exists (select 1 from public.reviews r where r.id = review_id and r.user_id = (select auth.uid())));

create policy "Users can tag their own reviews"
  on public.review_tags for insert
  to authenticated
  with check (exists (select 1 from public.reviews r where r.id = review_id and r.user_id = (select auth.uid())));

create policy "Users can untag their own reviews"
  on public.review_tags for delete
  to authenticated
  using (exists (select 1 from public.reviews r where r.id = review_id and r.user_id = (select auth.uid())));

------------------------------------------------------------------------------
-- save_review: create or update the caller's review and replace its tags, in one step.
-- Runs with the caller's permissions (security invoker), so the reviews/review_tags
-- policies still apply (e.g. new reviews only for books marked read).
------------------------------------------------------------------------------

create or replace function public.save_review(
  p_book_id uuid,
  p_rating smallint,
  p_body text,
  p_tropes text[] default '{}',
  p_warnings text[] default '{}'
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_body text := nullif(trim(coalesce(p_body, '')), '');
begin
  if v_uid is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;
  if coalesce(cardinality(p_tropes), 0) > 50 or coalesce(cardinality(p_warnings), 0) > 50 then
    raise exception 'Choose at most 50 tropes and 50 content warnings' using errcode = '22023';
  end if;

  select id into v_id from public.reviews where user_id = v_uid and book_id = p_book_id;
  if v_id is null then
    returning id into v_id;
  else
    update public.reviews set rating = p_rating, body = v_body where id = v_id;
  end if;

  delete from public.review_tags where review_id = v_id;
  select v_id, t.id
  from public.tags t
  where (t.kind = 'trope' and t.slug = any (coalesce(p_tropes, '{}')))
     or (t.kind = 'content_warning' and t.slug = any (coalesce(p_warnings, '{}')));

  return v_id;
end;
$$;

revoke execute on function public.save_review(uuid, smallint, text, text[], text[]) from public, anon;
grant execute on function public.save_review(uuid, smallint, text, text[], text[]) to authenticated;

------------------------------------------------------------------------------
-- book_tag_counts: for one book, how many readers picked each tag. Runs with elevated
-- rights (security definer) to count across everyone's private reviews, but returns only
-- totals: never who tagged what.
------------------------------------------------------------------------------

create or replace function public.book_tag_counts(p_book_id uuid)
returns table (kind public.tag_kind, slug text, name text, category text, readers bigint)
language sql
stable
security definer
set search_path = ''
as $$
  select t.kind, t.slug, t.name, t.category, count(distinct r.user_id) as readers
  from public.review_tags rt
  join public.reviews r on r.id = rt.review_id
  join public.tags t on t.id = rt.tag_id
  where r.book_id = p_book_id
  group by t.id
  order by readers desc, t.name;
$$;

revoke execute on function public.book_tag_counts(uuid) from public, anon;
grant execute on function public.book_tag_counts(uuid) to authenticated;

------------------------------------------------------------------------------
-- The lists (generated from supabase/data/tropes.csv and content_warnings.csv)
------------------------------------------------------------------------------

on conflict (kind, slug) do update
  set name = excluded.name, category = excluded.category, position = excluded.position;
